SELECT e.event_id,a.student_id case_id,e.activity,e.timestamp FROM (SELECT 'LC:assignment:' || assignment_id || ':2' event_id, 'Assignment Submitted' activity, assignment_submitted_at timestamp,assignment_id object_key FROM assignment WHERE assignment_submitted_at IS NOT NULL) e JOIN assignment a ON a.assignment_id=e.object_key ORDER BY case_id,timestamp,event_id;
